import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"A3 Public Evidence Pack: Skill and Session Evidence Chain","description":"","frontmatter":{"title":"A3 Public Evidence Pack: Skill and Session Evidence Chain","date":"2026-08-28","updated":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"evidence-pack","edition":"research-center","summary":"Preserves 59 historical records and the old field-propagation probe, then adds the V2.1.2 SessionStore binding contract and independent-QA three-key and integrity results.","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/research/evidence/2026-08-28-skill-session-evidence.md","filePath":"en/research/evidence/2026-08-28-skill-session-evidence.md","lastUpdated":1788145987000}'),n={name:"en/research/evidence/2026-08-28-skill-session-evidence.md"};function r(d,e,l,o,h,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<p><a href="/joinwell52/zh/research/evidence/2026-08-28-skill-session-evidence">中文版本</a></p><h1 id="a3-skill-and-session-evidence-chain" tabindex="-1">A3 | Skill and Session Evidence Chain <a class="header-anchor" href="#a3-skill-and-session-evidence-chain" aria-label="Permalink to &quot;A3 | Skill and Session Evidence Chain&quot;">​</a></h1><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><p>A skill configuration existing, entering a Session, being actually invoked, and producing a valid engineering result are different facts. In the tested V2.0.4 ordinary skill path, <code>session_id</code> was used for runtime deduplication but was not persisted into the invocation evidence. That is a historical gap; the delivered V2.1.2 behavior is described below.</p><h2 id="historical-field-profile" tabindex="-1">Historical field profile <a class="header-anchor" href="#historical-field-profile" aria-label="Permalink to &quot;Historical field profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Correlation field</th><th style="text-align:right;">Present</th><th style="text-align:right;">Missing</th><th style="text-align:right;">Missing rate</th></tr></thead><tbody><tr><td><code>task_id</code></td><td style="text-align:right;">49</td><td style="text-align:right;">10</td><td style="text-align:right;">16.9%</td></tr><tr><td><code>session_id</code></td><td style="text-align:right;">0</td><td style="text-align:right;">59</td><td style="text-align:right;">100.0%</td></tr><tr><td><code>thread_key</code></td><td style="text-align:right;">42</td><td style="text-align:right;">17</td><td style="text-align:right;">28.8%</td></tr><tr><td><code>agent_id</code></td><td style="text-align:right;">15</td><td style="text-align:right;">44</td><td style="text-align:right;">74.6%</td></tr><tr><td><code>integrity</code></td><td style="text-align:right;">59</td><td style="text-align:right;">0</td><td style="text-align:right;">0%</td></tr></tbody></table><p>The latest sample date is 2026-08-12. The sample does not represent every current skill entry point. The sanitized mixed sample intentionally preserves both ordinary runtime-read records and planning evidence verified by Runtime authority; those evidence levels prove different things.</p><h2 id="re-runnable-public-attachments" tabindex="-1">Re-runnable public attachments <a class="header-anchor" href="#re-runnable-public-attachments" aria-label="Permalink to &quot;Re-runnable public attachments&quot;">​</a></h2><p>The Reader/check below validates field statistics and correlations in the frozen JSON sample. It does not execute the private Runtime. <code>current_probe</code> refers to the historical baseline at the time of the original research, not the version current on the day this page is read.</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A3-skill-session-fixture.json">Sanitized fixture</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A3-skill-session-reader.mjs">Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A3-skill-session-check.mjs">Check script</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/MANIFEST.txt">Attachment SHA-256 manifest</a></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node A3-skill-session-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;evidence_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RBE-20260828-A3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;records&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">59</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;session_id_missing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">59</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;session_id_missing_percent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;current_probe_persisted_task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;current_probe_persisted_thread&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;current_probe_persisted_session&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;mixed_evidence_levels&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><p>These materials do not mean every skill-evidence entry point lacked Session identity, do not prove that skill recommendations were wrong, and do not justify guessing historical Session identities to backfill missing records. Invocation evidence can prove an invocation occurred; it does not by itself prove task completion.</p><h2 id="_2026-08-30-v2-1-2-delivered-update" tabindex="-1">2026-08-30: V2.1.2 delivered update <a class="header-anchor" href="#_2026-08-30-v2-1-2-delivered-update" aria-label="Permalink to &quot;2026-08-30: V2.1.2 delivered update&quot;">​</a></h2><p>A pre-fix rerun on V2.1.1 <code>36e5c83b</code> confirmed that ordinary invocation records still lost Session identity. Implementation commit <code>3302ca61</code> added Runtime checks against SessionStore existence, Agent identity and existing task/thread context. Persisted evidence now distinguishes <code>verified / invalid_claim / not_applicable</code>, corresponding to a trusted binding, an invalid claim, and a legitimate sessionless operation backed by a Runtime reason.</p><p>Independent QA C1 on <code>64f633ac</code> used an actual SessionStore registration and observed one journal record, task/thread/session matching 3/3, <code>session_binding=verified</code>, <code>binding_reason=runtime_session_store_match</code>, <code>evidence_source=sdk_tool_call</code>, with integrity verification passing.</p><p>C1 is an internal acceptance identifier, not this public A3 pack number. The valid-binding case does not by itself prove forged-session rejection, sessionless handling or three-key presence on every call; those branches are covered by separate development tests. Delivered verification on the ordinary path also should not be expanded into a claim of complete Session-lifecycle auditing.</p><h2 id="sources-for-the-newer-claims-and-review-visibility" tabindex="-1">Sources for the newer claims and review visibility <a class="header-anchor" href="#sources-for-the-newer-claims-and-review-visibility" aria-label="Permalink to &quot;Sources for the newer claims and review visibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>First-party source</th><th>Visibility</th></tr></thead><tbody><tr><td>Pre-fix gap, SessionStore binding and failure branches</td><td><code>RUNTIME-BOUNDARY-20260830-001</code>: phase0, targeted records and implementation</td><td>Restricted mother-repository material</td></tr><tr><td>C1 three-key and integrity validation</td><td><code>RUNTIME-BOUNDARY-QA-20260830-001</code>: independent-qa records</td><td>Restricted mother-repository material</td></tr><tr><td>V2.1.2 formal release and final regression</td><td><code>V2.1.2-R3</code>, <code>V2.1.2-PUBLICATION-20260830-001</code>; Runtime 1842 pass / 0 fail / 1 skip, Shell 1037 pass / 0 fail</td><td>First-party release record, 2026-08-30</td></tr></tbody></table><p>The <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">CodeFlowMu V2.1.2 Public Release Summary</a> consolidates the SessionStore verification boundary, all three Runtime changes, C1 independent QA, compatibility, release gates and residual risk. Complete source and raw logs remain restricted first-party material and are not public reading links; the historical fixture is not presented as a V2.1.2 end-to-end reproduction kit.</p><p>V2.1.2 does not backfill historical Sessions and does not treat <code>outcome=ok</code> or a valid integrity digest as proof that a TASK is complete. Open Edition was not released as part of this patch and no online instance is implied to have switched. Existing warnings, the Windows symlink skip and untested real-deployment scope remain explicit.</p>',23)])])}const u=i(n,[["render",r]]);export{k as __pageData,u as default};
